var t=[{title:`Warum es wichtig ist`,text:`Mit dem Alter verändern sich oft Muskelmasse, Kraft, Schnellkraft und Gleichgewicht, wobei das Tempo von Mensch zu Mensch stark variiert. Krafttraining kann Alltagsaufgaben erleichtern, etwa das Aufstehen von einem Stuhl, Treppensteigen und das Tragen von Einkäufen. Aerobe Aktivität unterstützt die Herz-Kreislauf-Gesundheit und die Ausdauer.`},{title:`Mehrere Fähigkeiten trainieren`,text:`Eine praktische Woche mischt Krafttraining, moderate aerobe Aktivität und etwas Gleichgewichtsübung. Die offiziellen Empfehlungen für Erwachsene ab 65 nennen ausdrücklich mindestens 150 Minuten moderate aerobe Aktivität pro Woche, Muskelkräftigung an zwei Tagen und Gleichgewichtsarbeit. Folge in deinen Fünfzigern den allgemeinen Aktivitätsempfehlungen für Erwachsene.`},{title:`Nützliche Bewegungen wählen`,text:`Aufstehen aus dem Sitzen, gestützte Step-ups, Rudern, Drücken und Tragen lassen sich alle an deinen jetzigen Stand anpassen. Manche gesunden älteren Erwachsenen profitieren von beaufsichtigten Schnellkraftübungen, die mit Kontrolle und schneller Absicht gemacht werden. Das bedeutet nicht, ohne Vorbereitung in riskante Übungen mit hoher Belastung zu springen.`},{title:`Mit Rückmeldung steigern`,text:`Mache Übungen schwerer, wenn sich Geschick und Kraft verbessern, aber erwarte, dass die Erholung von Erkrankungen, Schlaf und früherem Training abhängt. Hole bei neuem Schwindel, Brustsymptomen, unerklärlichem Schmerz oder Gleichgewichtsproblemen fachlichen Rat. Dein Alter ist keine Diagnose und kann eine gründliche Untersuchung nicht ersetzen, und für sich allein ist es kein Grund, schwereres Training auszuschließen.`}];var i=[{label:`CDC: körperliche Aktivität für ältere Erwachsene`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/older-adults.html`},{label:`ACSM-Positionspapier 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var r={sections:t,sources:i};export{r as default,t as sections,i as sources};